    fc_pt_kp: "Taxa 0% para holding > 365 dias\n28% sobre ganhos de curto prazo\nDeclarar em Anexo G do IRS\nFIFO obrigatório por defeito\nLei n.º 24-D/2022, art. 5.º",
    fc_es_name: "Espanha", fc_es_short: "19–30%", fc_es_long: "19–30%", fc_es_thr: "Escalonado por ganho",
    fc_es_sum: "A Espanha trata as criptomoedas como ativos patrimoniais. As mais-valias são tributadas de forma escalonada: 19% até €6k, 21% de €6k–€50k, 23% de €50k–€200k, 27% de €200k–€300k e 30% acima de €300k (desde 2025). Sem distinção entre curto e longo prazo.",
    fc_es_kp: "19% até €6.000 de ganho\n21% entre €6k e €50k\n23% entre €50k e €200k\n27% entre €200k e €300k\n30% acima de €300k (novo escalão 2025)\nDeclarar na IRPF (Renda)",
    fc_fr_name: "França", fc_fr_short: "30%", fc_fr_long: "30%", fc_fr_thr: "Flat tax (PFU)",
    fc_fr_sum: "A França aplica um 'Prélèvement Forfaitaire Unique' (PFU) de 30% sobre todas as mais-valias cripto, independentemente do período de detenção. Inclui 12,8% de imposto e 17,2% de contribuições sociais.",
    fc_fr_kp: "Flat tax de 30% sobre todos os ganhos\n12,8% IR + 17,2% contribuições sociais\nSem benefício por tempo de detenção\nDeclarar na déclaration 2086\nIsenção se ganhos totais < €305/ano",
    fc_de_name: "Alemanha", fc_de_short: "Taxa marginal (até 45%)", fc_de_long: "Isento", fc_de_thr: "> 365 dias",
    fc_de_sum: "A Alemanha é dos países mais favoráveis: ganhos de ativos detidos mais de 1 ano são totalmente isentos. Para detenção inferior, aplica-se a taxa marginal de IRS pessoal (até 45%). Isenção também abaixo de €600 de ganho.",
    fc_de_kp: "Taxa 0% para holding > 1 ano\nTaxa marginal pessoal para < 1 ano\nIsenção se ganhos anuais < €600\nDeclarar na Anlage SO do Einkommensteuererklärung\nRegra especial para staking: < 10 anos",
    fc_uk_name: "Reino Unido", fc_uk_short: "18–24%", fc_uk_long: "18–24%", fc_uk_thr: "Por escalão de rendimento",
    fc_uk_sum: "O HMRC trata cripto como ativos de capital. Após o Autumn Budget de Out 2024, as taxas subiram: 18% para contribuintes de base e 24% para contribuintes superiores. Isenção anual de £3.000 (Annual Exempt Amount 2024/25). Sem distinção temporal.",
    fc_uk_kp: "18% para contribuintes básicos (era 10% até Out 2024)\n24% para contribuintes de taxa superior (era 20% até Out 2024)\nIsenção anual de £3.000\nRegras Section 104 pooling (custo médio)\nDeclarar via Self Assessment",
    fc_us_name: "EUA", fc_us_short: "10–37%", fc_us_long: "0–20%", fc_us_thr: "> 365 dias",
    fc_us_sum: "O IRS classifica cripto como 'property'. Ganhos de curto prazo (< 1 ano) são tributados à taxa marginal de rendimento ordinário (até 37%). Longo prazo: 0%, 15% ou 20% dependendo do rendimento. Obrigação adicional de reporte FBAR/FinCEN.",
    fc_us_kp: "0–20% para longo prazo (>1 ano)\n10–37% para curto prazo\nCada troca de cripto por cripto é evento tributável\nDeclarar via Form 8949 + Schedule D\nStaking/mining = rendimento ordinário",
    fc_ch_name: "Suíça", fc_ch_short: "Isento (private)", fc_ch_long: "Isento", fc_ch_thr: "Investidores privados",
    fc_ch_sum: "A Suíça é considerada um paraíso cripto. Para investidores privados, os ganhos de capital são geralmente isentos de imposto federal. Trading frequente pode ser considerado atividade profissional (tributado). O imposto sobre riqueza aplica-se ao valor detido.",
    fc_ch_kp: "Ganhos de capital isentos para privados\nTrading profissional = tributado como rendimento\nImposto sobre a fortuna (0,3–1%) sobre o valor\nDeclarar na declaração de impostos cantonal\nCada cantão tem regras ligeiramente diferentes",
    fc_ae_name: "Dubai / EAU", fc_ae_short: "0%", fc_ae_long: "0%", fc_ae_thr: "Sem imposto sobre ganhos",
    fc_ae_sum: "Os Emirados Árabes Unidos não têm imposto sobre o rendimento pessoal nem sobre mais-valias para pessoas singulares. Dubai é uma das jurisdições mais favoráveis do mundo para cripto, com regulação avançada via VARA.",
    fc_ae_kp: "0% de imposto sobre ganhos cripto\n0% de imposto sobre rendimento pessoal\nVARA regula exchanges e projetos cripto\nNecessário residência fiscal nos EAU\nEmpresas: 9% imposto sobre lucros > AED 375k",
    fc_nl_name: "Países Baixos", fc_nl_short: "33%", fc_nl_long: "33%", fc_nl_thr: "Box 3 (patrimônio)",
    fc_nl_sum: "Os Países Baixos tributam cripto através do 'Box 3' (poupanças e investimentos), um imposto sobre patrimônio com rendimento presumido. Em 2024, a taxa efetiva é de ~33% sobre um ganho fictício anual calculado pelo fisco, independentemente dos ganhos reais.",
    fc_nl_kp: "Tributação pelo Box 3 (rendimento fictício)\nTaxa efetiva ~33% em 2024\nNão distingue ganhos reais vs. ficticios\nCripto declarada como ativo em 1 de janeiro\nDiscussão legal em curso sobre a legalidade do Box 3",
    fc_it_name: "Itália", fc_it_short: "26%", fc_it_long: "26%", fc_it_thr: "> €2.000 de ganho anual",
    fc_it_sum: "A Itália aplica uma taxa plana de 26% sobre os ganhos de capital em cripto superiores a €2.000 por ano. Desde 2023, existe a opção de regularização de ativos com taxa reduzida. Nenhuma distinção entre curto e longo prazo.",
    fc_it_kp: "26% de taxa plana sobre mais-valias\nIsenção para ganhos anuais < €2.000\nSem distinção temporal (curto/longo prazo)\nOpção de regularização (2023) com taxa reduzida\nDeclarar no Quadro RT da declaração fiscal",
    fc_br_name: "Brasil", fc_br_short: "15–22,5%", fc_br_long: "15–22,5%", fc_br_thr: "Vendas > R$35.000/mês",
    fc_br_sum: "No Brasil, as criptomoedas são tratadas como ativos financeiros. Ganhos de capital em vendas acima de R$35.000/mês são tributados de 15% a 22,5% dependendo do montante. A Receita Federal exige declaração anual dos saldos em cripto.",
    fc_br_kp: "Isenção para vendas mensais ≤ R$35.000\n15% de ganhos até R$5 milhões\n17,5% entre R$5M e R$10M\n20% entre R$10M e R$30M\n22,5% acima de R$30M\nDeclarar na DIRPF via Programa GCAP",
    fc_ca_name: "Canadá", fc_ca_short: "~27% (50% de inclusão)", fc_ca_long: "~27% (50% de inclusão)", fc_ca_thr: "50% dos ganhos tributável",
    fc_ca_sum: "O Canadá trata cripto como propriedade. 50% dos ganhos de capital são incluídos no rendimento tributável. A taxa efetiva depende da taxa marginal de cada contribuinte. Em 2024, o governo propôs aumentar para 2/3 para ganhos acima de C$250k.",
    fc_ca_kp: "50% dos ganhos de capital incluídos no rendimento\nTaxa efetiva ~27% para a classe média\nSem distinção entre curto e longo prazo\nCada troca cripto-cripto é evento tributável\nDeclarar no Schedule 3 (T1 General)",
    fc_au_name: "Austrália", fc_au_short: "Até 45% (marginal)", fc_au_long: "50% desconto (>1 ano)", fc_au_thr: "> 365 dias para desconto",
    fc_au_sum: "A Austrália trata cripto como ativo de capital (CGT). Ganhos de curto prazo são tributados à taxa marginal (até 45%). Para ativos detidos mais de 12 meses, aplica-se um desconto de 50% no ganho. A ATO exige reporte de todas as transações.",
    fc_au_kp: "Desconto de 50% nos ganhos para posse > 12 meses\nCurto prazo: taxa marginal (até 45%)\nMining = rendimento ordinário\nCada troca cripto-cripto é evento tributável\nDeclarar no Tax Return via myTax",
    fc_sg_name: "Singapura", fc_sg_short: "0% (investidor privado)", fc_sg_long: "0% (investidor privado)", fc_sg_thr: "Sem CGT para privados",
    fc_sg_sum: "Singapura não tem imposto sobre mais-valias (CGT). Para investidores privados, os ganhos cripto são geralmente isentos de imposto. Se o trading for considerado atividade comercial habitual, os lucros podem ser tributados como rendimento empresarial. A MAS tem uma das regulações cripto mais avançadas da Ásia.",
    fc_sg_kp: "0% de imposto sobre mais-valias para investidores privados\nTrading habitual pode ser tributado como rendimento comercial\nGST (9%) pode aplicar-se a transações de serviços cripto\nMAS regula exchanges e projetos via Payment Services Act\nAmbiente muito favorável para empresas cripto e Web3",
    fc_sg: "Singapura",
