    // ── Política de Privacidade ──
    pp_title: "Política de Privacidade",
    pp_intro: "A tua privacidade é central no ChainFolioAI. Esta política explica que dados tratamos e porquê.",
    pp_s1_h: "Quem somos",
    pp_s1_b: "O ChainFolioAI é um painel de acompanhamento de investimentos cripto e tradicionais. Somos os responsáveis pelo tratamento dos dados que nos forneces ao usar a plataforma.",
    pp_s2_h: "Que dados recolhemos",
    pp_s2_b: "Dados de conta (email e autenticação via Supabase), endereços públicos de carteiras e chaves de API só-leitura que adicionas, preferências da aplicação e dados técnicos básicos de utilização. Nunca recolhemos chaves privadas nem frases-semente.",
    pp_s3_h: "Como usamos os dados",
    pp_s3_b: "Para autenticar a tua conta, agregar e mostrar o teu portefólio, calcular métricas e melhorar o serviço. Não vendemos os teus dados.",
    pp_s4_h: "Base legal (RGPD)",
    pp_s4_b: "Tratamos os dados com base na execução do contrato (prestação do serviço), no teu consentimento e no nosso interesse legítimo em manter e melhorar a plataforma.",
    pp_s5_h: "Partilha com terceiros",
    pp_s5_b: "Usamos subprocessadores para funcionar: Supabase (autenticação e base de dados), Stripe (pagamentos), Vercel (alojamento) e fornecedores de dados de mercado e on-chain. Cada um trata apenas o necessário para a sua função.",
    pp_s6_h: "Segurança e chaves",
    pp_s6_b: "A plataforma é 100% só-leitura: não temos custódia dos teus fundos nem acesso a chaves privadas. Os dados são transmitidos por ligações encriptadas.",
    pp_s7_h: "Os teus direitos",
    pp_s7_b: "Tens direito a aceder, corrigir, exportar e apagar os teus dados e a retirar o consentimento a qualquer momento. Podes eliminar carteiras e a conta diretamente na aplicação.",
    pp_s8_h: "Contacto",
    pp_s8_b: "Para questões de privacidade, contacta-nos através do email de suporte indicado na tua conta.",

    // ── Termos de Serviço ──
    tp_title: "Termos de Serviço",
    tp_intro: "Ao usar o ChainFolioAI, concordas com estes termos. Lê-os com atenção.",
    tp_s1_h: "Aceitação dos termos",
    tp_s1_b: "Ao criar uma conta ou usar a plataforma, aceitas ficar vinculado a estes termos. Se não concordares, não uses o serviço.",
    tp_s2_h: "O serviço",
    tp_s2_b: "O ChainFolioAI agrega e mostra informação sobre os teus ativos cripto e tradicionais, com métricas, fiscalidade e um assistente de IA. A informação é fornecida tal como está, para fins informativos.",
    tp_s3_h: "Não é aconselhamento financeiro",
    tp_s3_b: "Nada na plataforma constitui aconselhamento financeiro, de investimento, fiscal ou jurídico. As decisões de investimento são da tua inteira responsabilidade.",
    tp_s4_h: "Só-leitura e sem custódia",
    tp_s4_b: "A plataforma é só-leitura: nunca movemos fundos, nunca assinamos transações e nunca temos acesso às tuas chaves privadas ou seed. Nunca te pediremos essas chaves.",
    tp_s5_h: "Planos e pagamentos",
    tp_s5_b: "Os planos pagos são processados de forma segura pela Stripe. Podes cancelar a qualquer momento; o acesso mantém-se até ao fim do período pago.",
    tp_s6_h: "Limitação de responsabilidade",
    tp_s6_b: "Os dados podem conter erros, atrasos ou imprecisões das fontes externas. Na medida permitida por lei, não somos responsáveis por perdas resultantes do uso da plataforma.",
    tp_s7_h: "Alterações aos termos",
    tp_s7_b: "Podemos atualizar estes termos. As alterações materiais serão comunicadas e a data de atualização será revista.",
    tp_s8_h: "Contacto",
    tp_s8_b: "Para questões sobre estes termos, contacta-nos através do email de suporte indicado na tua conta.",
