    dash_cta_pro_title: "Upgrade to Pro — no limits",
    dash_cta_pro_desc: "With Pro you get unlimited wallets, integrated CEX, whale alerts, 1-year history, CSV/PDF exports and a daily AI briefing.",
    dash_cta_premium_eyebrow: "💎 Next level",
    dash_cta_premium_title: "Upgrade to Premium — unlock the AI Manager",
    dash_cta_premium_desc: "With Premium you get the Dedicated AI Manager that analyzes your real portfolio, real-time Smart Money, REST API and MCP integration with Claude and Cursor.",
    dash_how_title: "How It Works",
    dash_how_subtitle: "A quick end-to-end summary of the platform.",
    dash_how_1_title: "What is ChainFolioAI",
    dash_how_1_desc: "ChainFolioAI brings your entire crypto and traditional net worth into a single dashboard. You see the total value, profit/loss (PNL) for the day, the last 30 days and since inception, the allocation by currency and how it evolves over time. It's 100% read-only: we never sign transactions, never ask for your private keys or seed phrase, and can never touch your funds.",
    dash_how_2_title: "How to connect your wallets",
    dash_how_2_desc: "Simple and safe: in Wallets, you just paste your wallet's public address (ETH, SOL, BTC, ADA and more networks). From there we read the blockchain directly to compute balances, DeFi positions, NFTs and the euro value — all updated automatically. You can connect several wallets and also exchanges (Binance, Kraken, CoinEx) and Hyperliquid on paid plans.",
    dash_how_3_title: "Where the data comes from",
    dash_how_3_desc: "We only use reliable, real-time sources: crypto prices via CoinGecko, stocks and indices via Twelve Data, on-chain balances via Blockfrost (Cardano), Moralis (EVM/Solana) and mempool.space (Bitcoin), and news via CoinDesk, CoinTelegraph and Reuters. The values you see are real and verifiable, not estimates.",
    dash_how_4_title: "What the AI does",
    dash_how_4_desc: "The AI is an assistant, not a fortune-teller. The daily briefing and AI Manager use language models to read the real data from your portfolio and the market and help you interpret it — summarize the day, explain moves, simulate tax or FIRE scenarios. It always works from real numbers and never makes up prices or quotes.",
    dash_how_5_title: "Your data privacy and security",
    dash_how_5_desc: "Your privacy comes first. Wallet addresses are hidden by default, with a button to show/hide them whenever you want. We never share or sell your data, and because the app is read-only, even in the event of unauthorized access no one can move your funds. You can enable automatic daily snapshots in Account to build up a PNL history over time.",
    dash_how_6_title: "Available plans",
    dash_how_6_desc: "Start free and grow when you need to. The Free plan gives you the essentials (up to 3 wallets, live market, tax and FIRE tools). Pro unlocks unlimited wallets, exchanges, extended history, whale alerts and an AI email briefing. Premium adds the Dedicated AI Manager, real-time Smart Money, API/MCP access and every tax country. Cancel anytime.",
    df_wallets_l: "Wallets & Balances",
    df_wallets_s: "Connect your crypto wallets (ETH, SOL, BTC, ADA and more) in read-only mode, using just the public address. We never ask for or store private keys or seed phrases.",
    df_wallets_0: "Up to 3 wallets (ETH, SOL, BTC, ADA)",
    df_wallets_1: "Unlimited wallets + CEX (Binance, Kraken, CoinEx) + Hyperliquid + Ledger/Trezor",
