    pc_faq_title: "Frequently asked questions",
    pc_faq_q1: "Is it safe to connect my wallets?",
    pc_faq_a1: "Yes. We only use your public address, in read-only mode. We never ask for — nor can we access — your private keys or seed phrase, and we never sign transactions.",
    pc_faq_q2: "Do I need a card for the free plan?",
    pc_faq_a2: "No. The Free plan is free forever and requires no card. We only ask for payment details if you choose to upgrade to Pro or Premium.",
    pc_faq_q3: "Can I cancel anytime?",
    pc_faq_a3: "Yes, anytime from your account. You keep access to paid features until the end of the period you've already paid for, with no renewal after that.",
    pc_faq_q4: "How does payment work?",
    pc_faq_a4: "Payments are processed securely by Stripe, by card. The subscription renews automatically every month until you cancel.",
    pc_faq_q5: "Can I change plans later?",
