    fire_title: "FIRE Calculator",
    fire_subtitle: "Financial Independence, Retire Early — calculate when you can be financially free.",
    fire_intro_title: "How this calculator works",
    fire_intro_1: "FIRE (Financial Independence, Retire Early) is the point where your investments earn enough to cover your expenses — you no longer depend on a salary.",
    fire_intro_2: "The 4% rule: it's assumed you can withdraw 4% of your wealth per year without depleting it. So the goal is to build 25× your annual expenses (100% ÷ 4%).",
    fire_intro_3: "What matters is the real return — your investment return minus inflation. Adjust the controls below (expenses, monthly savings, expected return) and see in how many years you get there.",
