    fc_legal_notice: "Legal notice:",
    fc_pt_name: "Portugal", fc_pt_short: "28%", fc_pt_long: "Exempt", fc_pt_thr: "> 365 days",
    fc_pt_sum: "Crypto gains held for more than 365 days are tax-exempt (since 2023). Below that, a 28% rate applies on profit. Must be declared in the IRS (Annex G).",
    fc_pt_kp: "0% rate for holding > 365 days\n28% on short-term gains\nDeclare in IRS Annex G\nFIFO mandatory by default\nLaw no. 24-D/2022, art. 5",
    fc_es_name: "Spain", fc_es_short: "19–30%", fc_es_long: "19–30%", fc_es_thr: "Tiered by gain",
    fc_es_sum: "Spain treats cryptocurrencies as capital assets. Gains are taxed in tiers: 19% up to €6k, 21% from €6k–€50k, 23% from €50k–€200k, 27% from €200k–€300k and 30% above €300k (since 2025). No distinction between short and long term.",
    fc_es_kp: "19% up to €6,000 gain\n21% between €6k and €50k\n23% between €50k and €200k\n27% between €200k and €300k\n30% above €300k (new 2025 tier)\nDeclare in IRPF (income)",
    fc_fr_name: "France", fc_fr_short: "30%", fc_fr_long: "30%", fc_fr_thr: "Flat tax (PFU)",
    fc_fr_sum: "France applies a 'Prélèvement Forfaitaire Unique' (PFU) of 30% on all crypto gains, regardless of holding period. Includes 12.8% tax and 17.2% social contributions.",
    fc_fr_kp: "Flat 30% tax on all gains\n12.8% income tax + 17.2% social contributions\nNo benefit for holding time\nDeclare in déclaration 2086\nExempt if total gains < €305/year",
    fc_de_name: "Germany", fc_de_short: "Marginal rate (up to 45%)", fc_de_long: "Exempt", fc_de_thr: "> 365 days",
    fc_de_sum: "Germany is one of the most favorable: gains from assets held over 1 year are fully exempt. For shorter holding, the personal marginal income tax rate applies (up to 45%). Also exempt below €600 of gain.",
    fc_de_kp: "0% rate for holding > 1 year\nPersonal marginal rate for < 1 year\nExempt if annual gains < €600\nDeclare in Anlage SO of the income tax return\nSpecial rule for staking: < 10 years",
    fc_uk_name: "United Kingdom", fc_uk_short: "18–24%", fc_uk_long: "18–24%", fc_uk_thr: "By income bracket",
    fc_uk_sum: "HMRC treats crypto as capital assets. After the Autumn Budget of Oct 2024, rates rose: 18% for basic-rate taxpayers and 24% for higher-rate taxpayers. Annual exemption of £3,000 (Annual Exempt Amount 2024/25). No time distinction.",
    fc_uk_kp: "18% for basic-rate taxpayers (was 10% until Oct 2024)\n24% for higher-rate taxpayers (was 20% until Oct 2024)\nAnnual exemption of £3,000\nSection 104 pooling rules (average cost)\nDeclare via Self Assessment",
    fc_us_name: "USA", fc_us_short: "10–37%", fc_us_long: "0–20%", fc_us_thr: "> 365 days",
    fc_us_sum: "The IRS classifies crypto as 'property'. Short-term gains (< 1 year) are taxed at the ordinary income marginal rate (up to 37%). Long term: 0%, 15% or 20% depending on income. Additional FBAR/FinCEN reporting obligation.",
    fc_us_kp: "0–20% for long term (>1 year)\n10–37% for short term\nEvery crypto-to-crypto swap is a taxable event\nDeclare via Form 8949 + Schedule D\nStaking/mining = ordinary income",
    fc_ch_name: "Switzerland", fc_ch_short: "Exempt (private)", fc_ch_long: "Exempt", fc_ch_thr: "Private investors",
    fc_ch_sum: "Switzerland is considered a crypto haven. For private investors, capital gains are generally exempt from federal tax. Frequent trading may be considered professional activity (taxed). Wealth tax applies to the value held.",
    fc_ch_kp: "Capital gains exempt for private individuals\nProfessional trading = taxed as income\nWealth tax (0.3–1%) on the value\nDeclare in the cantonal tax return\nEach canton has slightly different rules",
    fc_ae_name: "Dubai / UAE", fc_ae_short: "0%", fc_ae_long: "0%", fc_ae_thr: "No tax on gains",
    fc_ae_sum: "The United Arab Emirates has no personal income tax or capital gains tax for individuals. Dubai is one of the most favorable jurisdictions in the world for crypto, with advanced regulation via VARA.",
    fc_ae_kp: "0% tax on crypto gains\n0% personal income tax\nVARA regulates exchanges and crypto projects\nUAE tax residency required\nCompanies: 9% tax on profits > AED 375k",
    fc_nl_name: "Netherlands", fc_nl_short: "33%", fc_nl_long: "33%", fc_nl_thr: "Box 3 (wealth tax)",
    fc_nl_sum: "The Netherlands taxes crypto through 'Box 3' (savings and investments), a wealth tax on deemed returns. In 2024, the effective rate is ~33% on a fictitious annual gain calculated by the tax authority, regardless of actual gains.",
    fc_nl_kp: "Box 3 taxation (deemed return)\nEffective rate ~33% in 2024\nNo distinction between real vs. fictitious gains\nCrypto declared as asset on 1 January\nOngoing legal debate about Box 3 legality",
    fc_it_name: "Italy", fc_it_short: "26%", fc_it_long: "26%", fc_it_thr: "> €2,000 annual gain",
    fc_it_sum: "Italy applies a flat 26% rate on crypto capital gains above €2,000 per year. Since 2023, there is an option to regularize assets at a reduced rate. No distinction between short and long term.",
    fc_it_kp: "26% flat rate on capital gains\nExemption for annual gains < €2,000\nNo time distinction (short/long term)\nRegularization option (2023) at reduced rate\nDeclare in Quadro RT of the tax return",
    fc_br_name: "Brazil", fc_br_short: "15–22.5%", fc_br_long: "15–22.5%", fc_br_thr: "Sales > R$35,000/month",
    fc_br_sum: "In Brazil, cryptocurrencies are treated as financial assets. Capital gains on monthly sales above R$35,000 are taxed from 15% to 22.5% depending on the amount. The Receita Federal requires annual declaration of crypto balances.",
    fc_br_kp: "Exempt for monthly sales ≤ R$35,000\n15% on gains up to R$5 million\n17.5% between R$5M and R$10M\n20% between R$10M and R$30M\n22.5% above R$30M\nDeclare on DIRPF via Programa GCAP",
    fc_ca_name: "Canada", fc_ca_short: "~27% (50% inclusion)", fc_ca_long: "~27% (50% inclusion)", fc_ca_thr: "50% of gains taxable",
    fc_ca_sum: "Canada treats crypto as property. 50% of capital gains are included in taxable income. The effective rate depends on each taxpayer's marginal rate. In 2024, the government proposed increasing to 2/3 for gains above C$250k.",
    fc_ca_kp: "50% of capital gains included in income\nEffective rate ~27% for middle class\nNo distinction between short and long term\nEvery crypto-to-crypto swap is a taxable event\nDeclare on Schedule 3 (T1 General)",
    fc_au_name: "Australia", fc_au_short: "Up to 45% (marginal)", fc_au_long: "50% discount (>1 yr)", fc_au_thr: "> 365 days for discount",
    fc_au_sum: "Australia treats crypto as a capital asset (CGT). Short-term gains are taxed at the marginal rate (up to 45%). For assets held more than 12 months, a 50% CGT discount applies. The ATO requires reporting of all transactions.",
    fc_au_kp: "50% CGT discount for holdings > 12 months\nShort term: marginal rate (up to 45%)\nMining = ordinary income\nEvery crypto-to-crypto swap is a taxable event\nDeclare on Tax Return via myTax",
    fc_sg_name: "Singapore", fc_sg_short: "0% (private investor)", fc_sg_long: "0% (private investor)", fc_sg_thr: "No CGT for individuals",
    fc_sg_sum: "Singapore has no capital gains tax (CGT). For private investors, crypto gains are generally exempt from tax. If trading is considered a regular business activity, profits may be taxed as business income. The MAS has one of the most advanced crypto regulatory frameworks in Asia.",
    fc_sg_kp: "0% capital gains tax for private investors\nHabitual trading may be taxed as business income\nGST (9%) may apply to crypto service transactions\nMAS regulates exchanges via the Payment Services Act\nVery favorable environment for crypto and Web3 companies",
    fc_sg: "Singapore",
