    // ── Privacy Policy ──
    pp_title: "Privacy Policy",
    pp_intro: "Your privacy is central to ChainFolioAI. This policy explains what data we process and why.",
    pp_s1_h: "Who we are",
    pp_s1_b: "ChainFolioAI is a dashboard for tracking crypto and traditional investments. We are the controller of the data you provide when using the platform.",
    pp_s2_h: "What data we collect",
    pp_s2_b: "Account data (email and authentication via Supabase), public wallet addresses and read-only API keys you add, app preferences and basic technical usage data. We never collect private keys or seed phrases.",
    pp_s3_h: "How we use the data",
    pp_s3_b: "To authenticate your account, aggregate and display your portfolio, compute metrics and improve the service. We do not sell your data.",
    pp_s4_h: "Legal basis (GDPR)",
    pp_s4_b: "We process data on the basis of performance of the contract (providing the service), your consent and our legitimate interest in maintaining and improving the platform.",
    pp_s5_h: "Sharing with third parties",
    pp_s5_b: "We use sub-processors to operate: Supabase (authentication and database), Stripe (payments), Vercel (hosting) and market and on-chain data providers. Each handles only what is needed for its function.",
    pp_s6_h: "Security and keys",
    pp_s6_b: "The platform is 100% read-only: we do not custody your funds or access private keys. Data is transmitted over encrypted connections.",
    pp_s7_h: "Your rights",
    pp_s7_b: "You have the right to access, correct, export and delete your data and to withdraw consent at any time. You can remove wallets and your account directly in the app.",
    pp_s8_h: "Contact",
    pp_s8_b: "For privacy questions, contact us via the support email shown in your account.",

