    tp_s1_b: "By creating an account or using the platform, you agree to be bound by these terms. If you do not agree, do not use the service.",
    tp_s2_h: "The service",
    tp_s2_b: "ChainFolioAI aggregates and displays information about your crypto and traditional assets, with metrics, tax reporting and an AI assistant. Information is provided as is, for informational purposes.",
    tp_s3_h: "Not financial advice",
    tp_s3_b: "Nothing on the platform constitutes financial, investment, tax or legal advice. Investment decisions are entirely your own responsibility.",
    tp_s4_h: "Read-only and non-custodial",
    tp_s4_b: "The platform is read-only: we never move funds, never sign transactions and never have access to your private keys or seed. We will never ask you for those keys.",
