    dash_cta_pro_eyebrow: "🚀 Empieza a invertir mejor",
    dash_cta_pro_title: "Mejora a Pro — sin límites",
    dash_cta_pro_desc: "Con Pro tienes carteras ilimitadas, CEX integrado, alertas de ballenas, historial de 1 año, exportaciones CSV/PDF y briefing IA diario.",
    dash_cta_premium_eyebrow: "💎 Siguiente nivel",
    dash_cta_premium_title: "Mejora a Premium — desbloquea el Gestor IA",
    dash_cta_premium_desc: "Con Premium tienes el Gestor Dedicado IA que analiza tu cartera real, Smart Money en tiempo real, API REST e integración MCP con Claude y Cursor.",
    dash_how_title: "Cómo Funciona",
    dash_how_subtitle: "Un resumen rápido de la plataforma, de principio a fin.",
    dash_how_1_title: "Qué es ChainFolioAI",
    dash_how_1_desc: "ChainFolioAI reúne en un solo panel todo tu patrimonio cripto y tradicional. Ves el valor total, la ganancia/pérdida (PNL) del día, de los últimos 30 días y desde el inicio, la distribución por moneda y su evolución en el tiempo. Es 100% de solo lectura: nunca firmamos transacciones, nunca pedimos tus claves privadas o seed phrase, y nunca podemos tocar tus fondos.",
    dash_how_2_title: "Cómo conectar tus carteras",
    dash_how_2_desc: "Sencillo y seguro: en Carteras, solo pegas la dirección pública de tu wallet (ETH, SOL, BTC, ADA y más redes). A partir de ahí leemos la blockchain directamente para calcular saldos, posiciones DeFi, NFTs y el valor en euros — todo actualizado automáticamente. Puedes conectar varias carteras y también exchanges (Binance, Kraken, CoinEx) e Hyperliquid en los planes de pago.",
    dash_how_3_title: "De dónde vienen los datos",
    dash_how_3_desc: "Solo usamos fuentes fiables y en tiempo real: precios de cripto vía CoinGecko, acciones e índices vía Twelve Data, saldos on-chain vía Blockfrost (Cardano), Moralis (EVM/Solana) y mempool.space (Bitcoin), y noticias vía CoinDesk, CoinTelegraph y Reuters. Los valores que ves son reales y verificables, no estimaciones.",
    dash_how_4_title: "Qué hace la IA",
    dash_how_4_desc: "La IA es un asistente, no un adivino. El briefing diario y el Gestor IA usan modelos de lenguaje para leer los datos reales de tu cartera y del mercado y ayudarte a interpretarlos — resumir el día, explicar movimientos, simular escenarios fiscales o FIRE. Siempre trabaja a partir de números reales y nunca inventa precios ni cotizaciones.",
    dash_how_5_title: "Privacidad y seguridad de tus datos",
    dash_how_5_desc: "Tu privacidad es lo primero. Las direcciones de las carteras están ocultas por defecto, con un botón para mostrar/ocultar cuando quieras. Nunca compartimos ni vendemos tus datos, y como la app es de solo lectura, incluso ante un acceso indebido nadie puede mover tus fondos. Puedes activar el snapshot diario automático en Cuenta para construir un historial de PNL con el tiempo.",
    dash_how_6_title: "Planes disponibles",
    dash_how_6_desc: "Empieza gratis y crece cuando lo necesites. El plan Free te da lo esencial (hasta 3 carteras, mercado en vivo, fiscalidad y FIRE). Pro desbloquea carteras ilimitadas, exchanges, historial ampliado, alertas de ballenas y briefing IA por email. Premium añade el Gestor Dedicado IA, Smart Money en tiempo real, acceso vía API/MCP y todos los países fiscales. Cancela cuando quieras.",
    df_wallets_l: "Carteras y Saldos",
    df_wallets_s: "Conecta tus carteras cripto (ETH, SOL, BTC, ADA y más) en modo lectura, usando solo la dirección pública. Nunca pedimos ni guardamos claves privadas o seed phrases.",
