    fire_intro_title: "Cómo funciona esta calculadora",
    fire_intro_1: "FIRE (Financial Independence, Retire Early) es el momento en que tus inversiones rinden lo suficiente para cubrir tus gastos — dejas de depender del salario.",
    fire_intro_2: "Regla del 4%: se asume que puedes retirar el 4% de tu patrimonio al año sin agotarlo. Por eso el objetivo es acumular 25× tus gastos anuales (100% ÷ 4%).",
