    pp_title: "Política de Privacidad",
    pp_intro: "Tu privacidad es central en ChainFolioAI. Esta política explica qué datos tratamos y por qué.",
    pp_s1_h: "Quiénes somos",
    pp_s1_b: "ChainFolioAI es un panel para seguir inversiones cripto y tradicionales. Somos los responsables del tratamiento de los datos que nos facilitas al usar la plataforma.",
    pp_s2_h: "Qué datos recopilamos",
    pp_s2_b: "Datos de cuenta (email y autenticación vía Supabase), direcciones públicas de carteras y claves de API de solo lectura que añades, preferencias de la aplicación y datos técnicos básicos de uso. Nunca recopilamos claves privadas ni frases semilla.",
    pp_s3_h: "Cómo usamos los datos",
    pp_s3_b: "Para autenticar tu cuenta, agregar y mostrar tu cartera, calcular métricas y mejorar el servicio. No vendemos tus datos.",
    pp_s4_h: "Base legal (RGPD)",
    pp_s4_b: "Tratamos los datos sobre la base de la ejecución del contrato (prestación del servicio), tu consentimiento y nuestro interés legítimo en mantener y mejorar la plataforma.",
    pp_s5_h: "Compartir con terceros",
    pp_s5_b: "Usamos subencargados para funcionar: Supabase (autenticación y base de datos), Stripe (pagos), Vercel (alojamiento) y proveedores de datos de mercado y on-chain. Cada uno trata solo lo necesario para su función.",
    pp_s6_h: "Seguridad y claves",
    pp_s6_b: "La plataforma es 100% de solo lectura: no custodiamos tus fondos ni accedemos a claves privadas. Los datos se transmiten por conexiones cifradas.",
    pp_s7_h: "Tus derechos",
    pp_s7_b: "Tienes derecho a acceder, corregir, exportar y eliminar tus datos y a retirar el consentimiento en cualquier momento. Puedes eliminar carteras y la cuenta directamente en la aplicación.",
    pp_s8_h: "Contacto",
    pp_s8_b: "Para cuestiones de privacidad, contáctanos a través del email de soporte indicado en tu cuenta.",

