    dash_cta_pro_eyebrow: "🚀 Investissez plus intelligemment",
    dash_cta_pro_title: "Passez à Pro — sans limites",
    dash_cta_pro_desc: "Avec Pro, vous avez des portefeuilles illimités, CEX intégré, alertes baleines, historique d'un an, exports CSV/PDF et briefing IA quotidien.",
    dash_cta_premium_eyebrow: "💎 Niveau supérieur",
    dash_cta_premium_title: "Passez à Premium — débloquez le Gestionnaire IA",
    dash_cta_premium_desc: "Avec Premium, vous avez le Gestionnaire IA Dédié qui analyse votre portefeuille réel, Smart Money en temps réel, API REST et intégration MCP avec Claude et Cursor.",
    dash_how_title: "Comment ça marche",
    dash_how_subtitle: "Un résumé rapide de la plateforme, de bout en bout.",
    dash_how_1_title: "Qu'est-ce que ChainFolioAI",
    dash_how_1_desc: "ChainFolioAI rassemble dans un seul tableau de bord tout votre patrimoine crypto et traditionnel. Vous voyez la valeur totale, le profit/perte (PNL) du jour, des 30 derniers jours et depuis le début, la répartition par devise et son évolution dans le temps. C'est 100% lecture seule : nous ne signons jamais de transactions, ne demandons jamais vos clés privées ou seed phrase, et ne pouvons jamais toucher à vos fonds.",
    dash_how_2_title: "Comment connecter vos portefeuilles",
    dash_how_2_desc: "Simple et sûr : dans Portefeuilles, vous collez simplement l'adresse publique de votre wallet (ETH, SOL, BTC, ADA et d'autres réseaux). Nous lisons ensuite la blockchain directement pour calculer les soldes, positions DeFi, NFT et la valeur en euros — le tout mis à jour automatiquement. Vous pouvez connecter plusieurs portefeuilles ainsi que des exchanges (Binance, Kraken, CoinEx) et Hyperliquid dans les formules payantes.",
    dash_how_3_title: "D'où viennent les données",
    dash_how_3_desc: "Nous n'utilisons que des sources fiables et en temps réel : prix crypto via CoinGecko, actions et indices via Twelve Data, soldes on-chain via Blockfrost (Cardano), Moralis (EVM/Solana) et mempool.space (Bitcoin), et actualités via CoinDesk, CoinTelegraph et Reuters. Les valeurs affichées sont réelles et vérifiables, pas des estimations.",
    dash_how_4_title: "Ce que fait l'IA",
    dash_how_4_desc: "L'IA est une assistante, pas une voyante. Le briefing quotidien et le Gestionnaire IA utilisent des modèles de langage pour lire les données réelles de votre portefeuille et du marché et vous aider à les interpréter — résumer la journée, expliquer les mouvements, simuler des scénarios fiscaux ou FIRE. Elle part toujours de chiffres réels et n'invente jamais de prix ni de cotations.",
    dash_how_5_title: "Confidentialité et sécurité de vos données",
    dash_how_5_desc: "Votre vie privée avant tout. Les adresses des portefeuilles sont masquées par défaut, avec un bouton pour les afficher/masquer quand vous voulez. Nous ne partageons ni ne vendons jamais vos données, et comme l'app est en lecture seule, même en cas d'accès non autorisé personne ne peut déplacer vos fonds. Vous pouvez activer le snapshot quotidien automatique dans Compte pour construire un historique de PNL au fil du temps.",
    dash_how_6_title: "Formules disponibles",
    dash_how_6_desc: "Commencez gratuitement et évoluez selon vos besoins. La formule Free vous donne l'essentiel (jusqu'à 3 portefeuilles, marché en direct, fiscalité et FIRE). Pro débloque les portefeuilles illimités, les exchanges, un historique étendu, les alertes de baleines et un briefing IA par email. Premium ajoute le Gestionnaire IA Dédié, le Smart Money en temps réel, l'accès API/MCP et tous les pays fiscaux. Annulez à tout moment.",
    df_wallets_l: "Portefeuilles et Soldes",
    df_wallets_s: "Connectez vos portefeuilles crypto (ETH, SOL, BTC, ADA et plus) en lecture seule, avec seulement l'adresse publique. Nous ne demandons ni ne stockons jamais de clés privées ou de seed phrases.",
    df_wallets_0: "Jusqu'à 3 portefeuilles (ETH, SOL, BTC, ADA)",
    df_wallets_1: "Portefeuilles illimités + CEX (Binance, Kraken, CoinEx) + Hyperliquid + Ledger/Trezor",
    df_wallets_2: "Tout Pro + synchronisation prioritaire",
    df_portfolio_l: "Portefeuille et PNL",
    df_portfolio_s: "Vue consolidée de tous vos actifs — portefeuilles, DeFi, NFT et exchanges — en un seul endroit, avec PNL quotidien et sur 30 jours, graphique d'évolution et répartition par devise.",
    df_portfolio_0: "30 jours d'historique, graphiques de base",
    df_portfolio_1: "365 jours + Score, Sharpe, CAGR, Max Drawdown, export CSV/PDF",
