    fire_title: "Calculateur FIRE",
    fire_subtitle: "Financial Independence, Retire Early — calculez quand vous pouvez être financièrement libre.",
    fire_intro_title: "Comment fonctionne ce calculateur",
    fire_intro_1: "FIRE (Financial Independence, Retire Early) est le moment où vos investissements rapportent assez pour couvrir vos dépenses — vous ne dépendez plus d'un salaire.",
    fire_intro_2: "La règle des 4% : on suppose que vous pouvez retirer 4% de votre patrimoine par an sans l'épuiser. L'objectif est donc d'accumuler 25× vos dépenses annuelles (100% ÷ 4%).",
    fire_intro_3: "Ce qui compte, c'est le rendement réel — le rendement de vos investissements moins l'inflation. Ajustez les curseurs ci-dessous (dépenses, épargne mensuelle, rendement attendu) et voyez en combien d'années vous y arrivez.",
